styleTag:
* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;

  width: 100%;
  height: 100%;

  overflow: hidden;

  background: transparent;

  font-family:
    "Segoe UI",
    Arial,
    Helvetica,
    sans-serif;
}



body {
  display: flex;

  align-items: center;
  justify-content: center;
}


#widget {
  position: relative;

  width: 420px;
  height: 110px;

  flex-shrink: 0;

  display: flex;
  align-items: center;

  gap: 16px;

  padding: 12px;

  background:
    rgba(20,
      20,
      28,
      0.92);

  border:
    1px solid rgba(255,
      255,
      255,
      0.10);

  border-radius: 18px;

  box-shadow: none;

  color: white;

  transform-origin:
    center center;

  transition:
    background 0.25s ease,
    opacity 0.25s ease,
    transform 0.25s ease;
}



#widget.track-transition {
  opacity: 0.58;
}



#album-container {
  position: relative;

  width: 86px;
  height: 86px;

  flex-shrink: 0;

  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}

#widget.track-transition #album-container {
  opacity: 0;

  transform:
    scale(0.94);
}

#album-art {
  width: 86px;
  height: 86px;

  display: block;

  object-fit: cover;

  border-radius: 13px;

  background:
    #2a2a35;

  box-shadow: none;

  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}



#music-indicator {
  display: none !important;
}



#track-info {
  position: relative;

  flex: 1;

  min-width: 0;

  height: 86px;

  display: flex;

  flex-direction: column;

  justify-content: center;

  gap: 5px;

  padding:
    12px 18px;

  background:
    transparent;

  border: none;

  border-radius: 18px;

  box-shadow: none;

  transition:
    background 0.25s ease,
    opacity 0.22s ease,
    transform 0.22s ease;
}

#widget.track-transition #track-info {
  opacity: 0;

  transform:
    translateY(4px);
}



#status {
  display: flex;

  align-items: center;

  gap: 6px;

  font-size: 11px;

  font-weight: 600;

  text-transform: uppercase;

  letter-spacing: 1.2px;

  color:
    var(--accent-color,
      #ffffff);
}

#status-dot {
  width: 6px;
  height: 6px;

  flex-shrink: 0;

  border-radius: 50%;

  background:
    #8d8d99;
}

#status.playing #status-dot {
  background:
    var(--accent-color,
      #ffffff);

  box-shadow:
    0 0 8px rgba(255,
      255,
      255,
      0.7);
}



#song-title {
  display: block;

  overflow: hidden;

  white-space: nowrap;

  text-overflow: ellipsis;

  font-size: 18px;

  font-weight: 700;

  line-height: 1.2;

  color:
    var(--accent-color,
      #ffffff);
}



#artist-name {
  display: block;

  overflow: hidden;

  white-space: nowrap;

  text-overflow: ellipsis;

  font-size: 14px;

  font-weight: 400;

  line-height: 1.2;

  color:
    var(--accent-color,
      #ffffff);

  opacity: 0.62;
}



#watermark {
  position: absolute;

  right: 14px;
  bottom: 8px;

  font-family:
    "Baskerville",
    "Times New Roman",
    serif;

  font-size: 13px;

  font-weight: 400;

  font-style: italic;

  line-height: 1.1;

  letter-spacing: 1.2px;

  color:
    var(--accent-color,
      #ffffff);

  opacity: 0.46;

  white-space: nowrap;

  pointer-events: none;

  user-select: none;

  transition:
    opacity 0.25s ease;
}

#widget.track-transition #watermark {
  opacity: 0.24;
}



#widget.idle #album-container {
  display: none;
}



#widget.dual-panel,
#widget.circle,
#widget.spinning-circle {
  background:
    transparent;

  border: none;

  box-shadow: none;
}

#widget.dual-panel #track-info,
#widget.circle #track-info,
#widget.spinning-circle #track-info {
  border:
    1px solid rgba(255,
      255,
      255,
      0.10);

  border-radius: 18px;

  box-shadow: none;
}



#widget.circle #album-art,
#widget.spinning-circle #album-art {
  border-radius: 50%;
}



#widget.spinning-circle #album-art {
  animation:
    zero-signal-spin 8s linear infinite;
}

#widget.spinning-circle.idle #album-art {
  animation-play-state:
    paused;
}

@keyframes zero-signal-spin {

  from {
    transform:
      rotate(0deg);
  }

  to {
    transform:
      rotate(360deg);
  }

}

scriptTag:
let settings = {

  username: '{lastfmUsername}',

  backgroundColor: '{backgroundColor}',

  accentColor: '{accentColor}',

  backgroundOpacity: Number('{backgroundOpacity}'),

  showAlbumArt: '{showAlbumArt}' === 'true',

  showStatus: '{showStatus}' === 'true',

  showCredit: '{showCredit}' === 'true',

  layout: '{layout}'

};



const UPDATE_INTERVAL = 3000;

const MAX_FAILURES = 3;

const TRANSITION_TIME = 220;



const API_URL =
  'https://zero-signal.vercel.app/api/lastfm';



const widget =
  document.getElementById('widget');


const trackInfo =
  document.getElementById('track-info');


const albumContainer =
  document.getElementById('album-container');


const albumArt =
  document.getElementById('album-art');


const songTitle =
  document.getElementById('song-title');


const artistName =
  document.getElementById('artist-name');


const status =
  document.getElementById('status');


const statusText =
  document.getElementById('status-text');


const musicIndicator =
  document.getElementById('music-indicator');


const watermark =
  document.getElementById('watermark');



let currentlyPlaying = false;

let currentArtworkURL = '';

let currentUsername = settings.username;

let currentTrackKey = '';

let consecutiveFailures = 0;

let hasReceivedValidData = false;

let requestGeneration = 0;

let requestInProgress = false;

let transitionGeneration = 0;





function clamp(value, min, max) {

  const number = Number(value);


  if (!Number.isFinite(number)) {

    return min;

  }


  return Math.min(

    max,

    Math.max(

      min,

      number

    )

  );

}







function normalizeBoolean(value) {

  if (typeof value === 'boolean') {

    return value;

  }


  return String(value).toLowerCase() === 'true';

}







function validHex(value) {

  return /^#[0-9a-fA-F]{6}$/.test(

    String(value)

  );

}







function hexToRgb(hex) {

  const clean =

    hex.replace('#', '');


  return {

    r: parseInt(

      clean.slice(0, 2),

      16

    ),


    g: parseInt(

      clean.slice(2, 4),

      16

    ),


    b: parseInt(

      clean.slice(4, 6),

      16

    )

  };

}







function normalizeLayout(value) {

  const layout =

    String(value)

      .trim()

      .toLowerCase();



  if (

    layout ===

    'dual panel'

  ) {

    return 'dual-panel';

  }



  if (

    layout ===

    'circle'

  ) {

    return 'circle';

  }



  if (

    layout ===

    'spinning circle'

  ) {

    return 'spinning-circle';

  }



  return 'standard';

}







function getTrackKey(track) {

  const title =

    track.name || '';



  const artist =

    track.artist &&

      track.artist['#text']

      ? track.artist['#text']

      : '';



  const mbid =

    track.mbid || '';



  return `${artist}|${title}|${mbid}`;

}







function wait(ms) {

  return new Promise(

    resolve =>

      setTimeout(

        resolve,

        ms

      )

  );

}







function applyLayout() {

  const layout =

    normalizeLayout(

      settings.layout

    );



  widget.classList.remove(

    'dual-panel',

    'circle',

    'spinning-circle'

  );



  if (

    layout ===

    'dual-panel'

  ) {

    widget.classList.add(

      'dual-panel'

    );

  }



  if (

    layout ===

    'circle'

  ) {

    widget.classList.add(

      'circle'

    );

  }



  if (

    layout ===

    'spinning-circle'

  ) {

    widget.classList.add(

      'spinning-circle'

    );

  }

}







function applyAppearance() {

  let background =

    settings.backgroundColor;



  if (!validHex(background)) {

    background =

      '#071a2b';

  }



  let accent =

    settings.accentColor;



  if (!validHex(accent)) {

    accent =

      '#69c5ff';

  }



  const opacity =

    clamp(

      settings.backgroundOpacity,

      0,

      100

    ) / 100;



  const rgb =

    hexToRgb(

      background

    );



  const backgroundValue =

    `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${opacity})`;



  const layout =

    normalizeLayout(

      settings.layout

    );



  applyLayout();



  if (

    layout ===

    'standard'

  ) {

    widget.style.background =

      backgroundValue;



    trackInfo.style.background =

      'transparent';

  } else {

    widget.style.background =

      'transparent';



    trackInfo.style.background =

      backgroundValue;

  }



  document.documentElement.style.setProperty(

    '--accent-color',

    accent

  );



  songTitle.style.color =

    accent;



  artistName.style.color =

    accent;



  status.style.color =

    accent;



  if (musicIndicator) {

    musicIndicator.style.background =

      accent;

  }



  status.style.display =

    settings.showStatus

      ? 'flex'

      : 'none';



  if (watermark) {

    watermark.style.display =

      settings.showCredit

        ? 'block'

        : 'none';

  }



  if (

    settings.showAlbumArt &&

    currentlyPlaying &&

    currentArtworkURL

  ) {

    albumContainer.style.display =

      'block';

  } else {

    albumContainer.style.display =

      'none';

  }

}





function findArtwork(track) {

  if (

    !track.image ||

    !Array.isArray(track.image)

  ) {

    return '';

  }



  const sizes = [

    'extralarge',

    'large',

    'medium',

    'small'

  ];



  for (

    const size of sizes

  ) {

    const image =

      track.image.find(

        item =>

          item.size ===

          size

      );



    if (

      image &&

      image['#text']

    ) {

      return image['#text'];

    }

  }



  return '';

}







async function transitionToTrack(

  track

) {

  const myTransition =

    ++transitionGeneration;



  widget.classList.add(

    'track-transition'

  );



  await wait(

    TRANSITION_TIME

  );



  if (

    myTransition !==

    transitionGeneration

  ) {

    return;

  }



  applyTrackData(

    track

  );



  requestAnimationFrame(

    () => {



      requestAnimationFrame(

        () => {



          if (

            myTransition !==

            transitionGeneration

          ) {

            return;

          }



          widget.classList.remove(

            'track-transition'

          );

        }

      );

    }

  );

}







function applyTrackData(track) {

  const newTrackKey =

    getTrackKey(track);



  currentTrackKey =

    newTrackKey;



  currentlyPlaying =

    true;



  hasReceivedValidData =

    true;



  consecutiveFailures =

    0;



  currentArtworkURL =

    '';



  albumArt.removeAttribute(

    'src'

  );



  albumContainer.style.display =

    'none';



  songTitle.textContent =

    track.name ||

    'Unknown Track';



  artistName.textContent =

    track.artist &&

      track.artist['#text']

      ? track.artist['#text']

      : 'Unknown Artist';



  widget.classList.remove(

    'idle'

  );



  status.classList.add(

    'playing'

  );



  statusText.textContent =

    'NOW PLAYING';



  if (musicIndicator) {

    musicIndicator.classList.remove(

      'idle'

    );

  }



  const artworkURL =

    findArtwork(track);



  if (!artworkURL) {

    applyAppearance();

    return;

  }



  const artworkTrackKey =

    newTrackKey;



  const newImage =

    new Image();



  newImage.onload =

    function () {



      if (

        artworkTrackKey !==

        currentTrackKey

      ) {

        return;

      }



      currentArtworkURL =

        artworkURL;



      albumArt.src =

        artworkURL;



      applyAppearance();

    };



  newImage.onerror =

    function () {



      if (

        artworkTrackKey !==

        currentTrackKey

      ) {

        return;

      }



      currentArtworkURL =

        '';



      albumArt.removeAttribute(

        'src'

      );



      applyAppearance();

    };



  newImage.src =

    artworkURL;



  applyAppearance();

}







function showPlaying(track) {

  const newTrackKey =

    getTrackKey(track);



  if (

    newTrackKey ===

    currentTrackKey

  ) {

    currentlyPlaying =

      true;



    consecutiveFailures =

      0;



    hasReceivedValidData =

      true;



    applyAppearance();



    return;

  }



  transitionToTrack(

    track

  );

}







function showNothingPlaying() {

  transitionGeneration++;



  widget.classList.remove(

    'track-transition'

  );



  currentlyPlaying =

    false;



  currentTrackKey =

    '';



  currentArtworkURL =

    '';



  hasReceivedValidData =

    true;



  consecutiveFailures =

    0;



  songTitle.textContent =

    'Nothing Playing';



  artistName.textContent =

    'No active Last.fm scrobble';



  albumArt.removeAttribute(

    'src'

  );



  albumContainer.style.display =

    'none';



  widget.classList.add(

    'idle'

  );



  status.classList.remove(

    'playing'

  );



  statusText.textContent =

    'NOT PLAYING';



  if (musicIndicator) {

    musicIndicator.classList.add(

      'idle'

    );

  }



  applyAppearance();

}







function showError() {

  transitionGeneration++;



  widget.classList.remove(

    'track-transition'

  );



  currentlyPlaying =

    false;



  currentTrackKey =

    '';



  currentArtworkURL =

    '';



  songTitle.textContent =

    'Last.fm Error';



  artistName.textContent =

    'Unable to load music';



  albumArt.removeAttribute(

    'src'

  );



  albumContainer.style.display =

    'none';



  widget.classList.add(

    'idle'

  );



  status.classList.remove(

    'playing'

  );



  statusText.textContent =

    'ERROR';



  if (musicIndicator) {

    musicIndicator.classList.add(

      'idle'

    );

  }



  applyAppearance();

}







function handleFailure(error) {

  consecutiveFailures++;



  if (error) {

    console.error(

      'Last.fm request failed:',

      error

    );

  }



  if (

    hasReceivedValidData &&

    consecutiveFailures <

    MAX_FAILURES

  ) {

    return;

  }



  if (

    consecutiveFailures >=

    MAX_FAILURES

  ) {

    showError();

  }

}







async function queryLastFM() {

  const username =

    String(

      currentUsername

    ).trim();



  if (!username) {

    showError();

    return;

  }



  const thisRequest =

    ++requestGeneration;



  try {

    const response =

      await fetch(

        `${API_URL}?username=${encodeURIComponent(username)}&_=${Date.now()}`,

        {

          cache:

            'no-store'

        }

      );



    if (

      thisRequest !==

      requestGeneration

    ) {

      return;

    }



    let data;



    try {

      data =

        await response.json();



    } catch (error) {

      handleFailure(error);

      return;

    }



    if (

      thisRequest !==

      requestGeneration

    ) {

      return;

    }



    if (

      !response.ok ||

      data.error

    ) {

      handleFailure(

        data.message ||

        data.error

      );



      return;

    }



    consecutiveFailures =

      0;



    const tracks =

      data.recenttracks &&

      data.recenttracks.track;



    if (!tracks) {

      showNothingPlaying();

      return;

    }



    const track =

      Array.isArray(tracks)

        ? tracks[0]

        : tracks;



    if (!track) {

      showNothingPlaying();

      return;

    }



    const isPlaying =

      track['@attr'] &&

      track['@attr']

        .nowplaying ===

      'true';



    if (isPlaying) {

      showPlaying(track);

    } else {

      showNothingPlaying();

    }



  } catch (error) {



    if (

      thisRequest !==

      requestGeneration

    ) {

      return;

    }



    handleFailure(error);

  }

}





window.onLiveVariableUpdate =

  function (

    nameOrData,

    incomingValue

  ) {



    let name =

      nameOrData;



    let value =

      incomingValue;



    if (

      nameOrData &&

      typeof nameOrData ===

      'object'

    ) {



      name =

        nameOrData.name ??

        nameOrData.variable ??

        nameOrData.key;



      value =

        nameOrData.value;

    }



    switch (name) {



      case 'backgroundColor':



        settings.backgroundColor =

          String(value);



        applyAppearance();



        break;





      case 'accentColor':



        settings.accentColor =

          String(value);



        applyAppearance();



        break;





      case 'backgroundOpacity':



        settings.backgroundOpacity =

          clamp(

            value,

            0,

            100

          );



        applyAppearance();



        break;





      case 'showAlbumArt':



        settings.showAlbumArt =

          normalizeBoolean(

            value

          );



        applyAppearance();



        break;





      case 'showStatus':



        settings.showStatus =

          normalizeBoolean(

            value

          );



        applyAppearance();



        break;





      case 'showCredit':



        settings.showCredit =

          normalizeBoolean(

            value

          );



        applyAppearance();



        break;





      case 'layout':



        settings.layout =

          String(value);



        applyAppearance();



        break;





      case 'lastfmUsername':



        currentUsername =

          String(value).trim();



        requestGeneration++;



        transitionGeneration++;



        currentTrackKey =

          '';



        currentArtworkURL =

          '';



        albumArt.removeAttribute(

          'src'

        );



        consecutiveFailures =

          0;



        hasReceivedValidData =

          false;



        queryLastFM();



        break;

    }

  };







async function pollLastFM() {



  if (requestInProgress) {

    return;

  }



  requestInProgress =

    true;



  try {



    await queryLastFM();



  } finally {



    requestInProgress =

      false;

  }

}









function scaleWidgetToContainer() {

  const designWidth = 420;

  const designHeight = 110;



  const availableWidth =

    window.innerWidth;



  const availableHeight =

    window.innerHeight;



  if (

    !availableWidth ||

    !availableHeight

  ) {

    return;

  }



  const scaleX =

    availableWidth /

    designWidth;



  const scaleY =

    availableHeight /

    designHeight;



  const scale =

    Math.min(

      scaleX,

      scaleY

    );





  widget.style.zoom =

    scale;

}





window.addEventListener(

  'resize',

  scaleWidgetToContainer

);





if (

  typeof ResizeObserver !==

  'undefined'

) {

  const resizeObserver =

    new ResizeObserver(

      function () {

        scaleWidgetToContainer();

      }

    );



  resizeObserver.observe(

    document.body

  );

}





applyAppearance();

scaleWidgetToContainer();

pollLastFM();



setInterval(

  pollLastFM,

  UPDATE_INTERVAL

);
